public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an HTTPS URL of a Web App to open from the side menu, a keyboardButtonTypeWebApp button, or an inlineQueryResultsButtonTypeWebApp button
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> GetWebAppUrlAsync(long botUserId = default, string url = default, WebAppOpenParameters parameters = default)
    {

           using var activity =  StartCallActivity("GetWebAppUrlAsync", typeof(GetWebAppUrl).FullName ?? "GetWebAppUrlAsync");

           try
           {
             return client.GetWebAppUrlAsync(botUserId, url, parameters);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
